window.CLD_MODEL = {"schemaVersion": "1.0", "version": "2026-10-20.1", "meta": {"title": "Built Environment Equity", "subtitle": "An evidence-traceable causal loop atlas", "problem": "Which factors cause inequity in the built environment setting and what are their effects on people? Which reinforcing or balancing feedback mechanisms created by those factors increase or decrease equity?", "definition": "Equity is the extent to which the built environment meets the differing needs of all groups through planning, design, construction, operation, management, regulation, governance, participation and policy making.", "definitionSource": "Supplied PPT, slide 1; attributed there to Seyedrezaei et al. (2023).", "definitionSourceUrl": "https://doi.org/10.1016/j.buildenv.2023.110827", "scope": "Urban neighborhood systems, primarily high-income settings represented in these reviews. Follow original low-income and otherwise underserved residents, alongside a locally defined better-served reference group. Age, disability, gender, ethnicity, tenure, climate and institutional context modify mechanisms; no universal group hierarchy is assumed.", "needs": ["Well-being", "Access", "Mobility", "Shelter", "Safety"], "limitations": ["Conceptual hypotheses, not causal identification, effect sizes, fitted simulation or proof of loop dominance. Solid reported mechanisms include authors' conceptual interpretations; they are not established causal effects.", "All disparity arrows require disproportionate priority-group change relative to the reference group. Average environmental or health improvement alone does not establish greater equity.", "Unmet-needs disparity represents separate needs-domain comparisons. No arbitrary composite score, weights or baseline values are invented. Health inequity additionally requires a judgment about unfairness and avoidability.", "R means amplification and B means counteraction; neither label determines whether equity improves. Highlighted loops are selected explanatory paths, not an exhaustive cycle inventory or a ranking of dominant dynamics.", "Policy loops require detection, mandate, political willingness, funding and delivery. Their response arrows are assumptions, and delays are qualitative modeling assumptions with no estimated duration.", "Contextual links can weaken, vanish or change sign. Density, displacement, noise inequity and active-travel injury exposure are not treated as universal effects.", "The 35-variable boundary omits separate food/diet, water/sanitation, climate drivers and discrimination variables. These remain important context or are aggregated into service access and housing barriers; the diagram is not a complete theory of every inequity.", "The six reviews overlap in underlying studies and are not six independent causal replications. Evidence anchors refer to review-level mechanisms unless explicitly stated otherwise.", "The PPT says six need categories but lists five; this model retains the five stated categories and does not invent a sixth. This is an interpretation requiring future stakeholder confirmation."], "readingGuide": "Start with a highlighted feedback loop, inspect each signed arrow, then compare the full network. A plus sign means same-direction change; a minus sign means opposite-direction change, with other relevant conditions held constant. Double bars mark plausible delays, not measured times.", "validationStatus": "Structural and provenance validation passed; empirical calibration and stakeholder validation remain future work.", "counts": {"variables": 35, "links": 78, "loops": 10, "sources": 6}}, "groups": [{"id": "governance", "label": "Resources & governance", "color": "#526b82"}, {"id": "housing", "label": "Housing & displacement", "color": "#b77946"}, {"id": "mobility", "label": "Access & mobility", "color": "#3e7b83"}, {"id": "place", "label": "Shared places & safety", "color": "#708a56"}, {"id": "health", "label": "Exposure & health", "color": "#8c6687"}, {"id": "equity", "label": "Between-group outcomes", "color": "#9c6373"}], "nodes": [{"id": "V01", "label": "Household financial resources", "group": "governance", "definition": "Income and material resources available to priority-group households before housing and energy costs. Distinct from neighborhood-average wealth.", "domains": ["Shelter", "Access"], "x": 150, "y": 160}, {"id": "V02", "label": "Resident decision-making influence", "group": "governance", "definition": "Neighborhood-level effective collective influence over planning, budgets and housing decisions. Influence can favor affluent newcomers; a neighborhood gain is not automatically greater voice for original priority residents.", "domains": ["Access", "Safety", "Shelter"], "x": 410, "y": 160}, {"id": "V03", "label": "Local public investment", "group": "governance", "definition": "Realized public spending on the focal neighborhood's housing, infrastructure and services. Its equity effect depends on allocation and resident retention.", "domains": ["Access", "Mobility", "Shelter"], "x": 670, "y": 160}, {"id": "V04", "label": "Equity policy response", "group": "governance", "definition": "Implemented response to monitored inequities, including resourcing and enforcement. An explicitly conditional institutional response, not an automatic reaction.", "domains": ["Well-being", "Access", "Mobility", "Shelter", "Safety"], "x": 930, "y": 160}, {"id": "V05", "label": "Affordable housing protection", "group": "governance", "definition": "Effective provision and preservation of affordable secure homes, tenant protections and anti-displacement measures for priority residents.", "domains": ["Shelter"], "x": 1190, "y": 160}, {"id": "V35", "label": "Neighborhood socioeconomic resources", "group": "governance", "definition": "Average resources of the resident population; changes may reflect who can afford to enter or remain. A compositional variable, not incumbent household income.", "domains": ["Access", "Shelter"], "x": 1450, "y": 160}, {"id": "V06", "label": "Healthy housing quality", "group": "housing", "definition": "Priority residents' access to homes with adequate ventilation, moisture control, thermal comfort and safe materials; energy performance is separately represented.", "domains": ["Shelter", "Well-being", "Safety"], "x": 150, "y": 430}, {"id": "V07", "label": "Housing energy efficiency", "group": "housing", "definition": "Energy performance of priority households' homes, with adequate ventilation and comfort maintained; implementation costs are not assumed away.", "domains": ["Shelter", "Well-being"], "x": 410, "y": 430}, {"id": "V09", "label": "Energy cost burden", "group": "housing", "definition": "Required household energy expenditure relative to resources, excluding rent or mortgage payments; higher means greater financial strain.", "domains": ["Shelter", "Well-being"], "x": 670, "y": 430}, {"id": "V08", "label": "Housing cost burden", "group": "housing", "definition": "Rent or mortgage and mandatory tenure costs relative to priority household resources; excludes the separately modeled household energy burden.", "domains": ["Shelter", "Access"], "x": 930, "y": 430}, {"id": "V12", "label": "Local housing costs", "group": "housing", "definition": "Local rents and purchase prices faced by entrants and renewing residents; price increases do not imply existing residents become wealthier.", "domains": ["Shelter"], "x": 1190, "y": 430}, {"id": "V13", "label": "Gentrification pressure", "group": "housing", "definition": "Market-led neighborhood upgrading and socioeconomic replacement pressure. Effects depend on tenure, timing, safeguards and local institutions.", "domains": ["Shelter", "Access"], "x": 1450, "y": 430}, {"id": "V10", "label": "Housing insecurity", "group": "housing", "definition": "Priority residents' uncertainty about retaining an adequate, affordable home; includes threatened loss and unstable tenure.", "domains": ["Shelter", "Well-being"], "x": 930, "y": 650}, {"id": "V11", "label": "Involuntary displacement", "group": "housing", "definition": "Forced or financially compelled residential moves among original priority residents; distinct from all residential mobility or cultural change alone.", "domains": ["Shelter", "Access", "Well-being"], "x": 1190, "y": 650}, {"id": "V18", "label": "Walkable land-use mix", "group": "mobility", "definition": "Connected proximity of everyday destinations and complementary uses. Density alone is deliberately not treated as uniformly beneficial.", "domains": ["Access", "Mobility"], "x": 150, "y": 880}, {"id": "V16", "label": "Inclusive public transport access", "group": "mobility", "definition": "Affordable, physically accessible, reliable public transport that meets priority groups' destinations and travel needs; distance to a stop alone is insufficient.", "domains": ["Access", "Mobility"], "x": 410, "y": 880}, {"id": "V17", "label": "Safe walking and cycling infrastructure", "group": "mobility", "definition": "Usable routes, safe crossings, separation and speed management, adapted to age, disability and other access needs.", "domains": ["Mobility", "Safety"], "x": 670, "y": 880}, {"id": "V21", "label": "Active travel and physical activity", "group": "mobility", "definition": "Walking, cycling and other physical activity among priority residents; benefits depend on access, safety and exposure conditions.", "domains": ["Mobility", "Well-being"], "x": 930, "y": 880}, {"id": "V19", "label": "Car-dependent travel", "group": "mobility", "definition": "Reliance on private motorized travel for everyday needs; changing this requires viable alternatives rather than simply restricting mobility.", "domains": ["Mobility", "Access"], "x": 1190, "y": 880}, {"id": "V20", "label": "Motor traffic volume", "group": "mobility", "definition": "Motor-vehicle traffic in places used by priority residents, with background fleet, road design and speeds held in context.", "domains": ["Mobility", "Safety"], "x": 1450, "y": 880}, {"id": "V14", "label": "Green and public-space quality", "group": "place", "definition": "Maintained, welcoming and effectively accessible shared green/public spaces for priority residents, rather than green acreage alone.", "domains": ["Access", "Well-being", "Safety"], "x": 150, "y": 1160}, {"id": "V15", "label": "Effective local service access", "group": "place", "definition": "Ability to use affordable, appropriate local services, including healthcare, healthy food and community amenities; includes financial and physical accessibility.", "domains": ["Access", "Well-being"], "x": 410, "y": 1160}, {"id": "V28", "label": "Social cohesion", "group": "place", "definition": "Inclusive trust, support and collective capacity among original priority residents; exclusionary bonding is not counted as an equity benefit.", "domains": ["Well-being", "Safety"], "x": 670, "y": 1160}, {"id": "V26", "label": "Neighborhood disorder", "group": "place", "definition": "Neglect and environmental disorder of shared places, without treating poverty or demographic composition itself as disorder.", "domains": ["Safety", "Well-being"], "x": 930, "y": 1160}, {"id": "V27", "label": "Perceived neighborhood safety", "group": "place", "definition": "Priority residents' perceived safety from crime and traffic danger when using streets and shared places; perceptions may differ from measured risk.", "domains": ["Safety", "Mobility", "Access"], "x": 1190, "y": 1160}, {"id": "V22", "label": "Traffic injury risk", "group": "place", "definition": "Population-level injury risk to priority residents from road traffic; not risk per walking trip. More exposure can raise injuries in unsafe conditions.", "domains": ["Safety", "Mobility", "Well-being"], "x": 1450, "y": 1160}, {"id": "V23", "label": "Air pollution exposure", "group": "health", "definition": "Priority residents' exposure to harmful outdoor pollutants. Traffic emissions are one driver; local dispersion and other sources remain contextual.", "domains": ["Well-being", "Safety"], "x": 150, "y": 1460}, {"id": "V24", "label": "Noise exposure", "group": "health", "definition": "Harmful environmental noise affecting priority residents; unequal exposure is context-dependent rather than assumed in every city.", "domains": ["Well-being", "Safety"], "x": 410, "y": 1460}, {"id": "V25", "label": "Heat exposure", "group": "health", "definition": "Harmful heat experienced by priority residents, conditional on shade, dwelling conditions, cooling access and individual vulnerability.", "domains": ["Well-being", "Safety"], "x": 670, "y": 1460}, {"id": "V29", "label": "Chronic stress", "group": "health", "definition": "Persistent psychosocial stress associated with financial strain, insecurity, environmental conditions and constrained control.", "domains": ["Well-being"], "x": 930, "y": 1460}, {"id": "V30", "label": "Physical ill health", "group": "health", "definition": "Physical morbidity and functional limitations in priority residents. The model represents direction, not a fitted disease incidence rate.", "domains": ["Well-being"], "x": 1190, "y": 1460}, {"id": "V31", "label": "Mental ill health", "group": "health", "definition": "Adverse mental health among priority residents, distinguished from stress as a mediating experience; no diagnosis is inferred for individuals.", "domains": ["Well-being"], "x": 1450, "y": 1460}, {"id": "V32", "label": "Work participation", "group": "health", "definition": "Priority residents' ability to obtain and sustain paid work. The health-to-work link is a synthesis hypothesis sensitive to labor protections.", "domains": ["Well-being", "Access"], "x": 1710, "y": 1460}, {"id": "V33", "label": "Unmet-needs disparity", "group": "equity", "definition": "Excess unmet built-environment needs among priority groups relative to a locally defined, better-served reference group. Higher means less equity. A conceptual set of domain-specific gaps, with no invented weighting or scalar score.", "domains": ["Well-being", "Access", "Mobility", "Shelter", "Safety"], "x": 1710, "y": 430}, {"id": "V34", "label": "Health inequity", "group": "equity", "definition": "Unfair, avoidable excess physical and mental ill health among priority groups relative to the local reference group; health inequality requires normative assessment to call it inequity.", "domains": ["Well-being"], "x": 1710, "y": 880}], "edges": [{"id": "E01", "source": "V35", "target": "V02", "polarity": 1, "rationale": "A better-resourced resident composition can support greater collective political influence.", "status": "reported", "evidence": ["A01"], "delay": false, "scope": "Neighborhood composition; not an effect of prices on incumbent income."}, {"id": "E02", "source": "V02", "target": "V03", "polarity": 1, "rationale": "Effective resident influence can attract and shape investment in the focal neighborhood.", "status": "reported", "evidence": ["A01", "A25"], "delay": true, "scope": "Allocation may favor already influential groups; investment is not intrinsically equitable."}, {"id": "E03", "source": "V29", "target": "V02", "polarity": -1, "rationale": "Sustained strain can reduce the capacity to organize and influence local decisions.", "status": "reported", "evidence": ["A02"], "delay": false, "scope": "Aggregate influence falls only where stressed priority residents form the relevant organizing base; influential newcomers can weaken this link."}, {"id": "E04", "source": "V01", "target": "V29", "polarity": -1, "rationale": "Greater household resources can buffer persistent financial and residential strain.", "status": "reported", "evidence": ["A02"], "delay": false, "scope": ""}, {"id": "E05", "source": "V03", "target": "V14", "polarity": 1, "rationale": "Spending directed to usable public spaces can improve their quality for priority residents.", "status": "synthesis", "evidence": ["A01", "A25"], "delay": true, "scope": "Assumes implementation, maintenance and effective priority-group access."}, {"id": "E06", "source": "V03", "target": "V15", "polarity": 1, "rationale": "Implemented service investment can improve affordable, appropriate local provision.", "status": "synthesis", "evidence": ["A01", "A12"], "delay": true, "scope": "Provision must address actual access barriers, not facility counts alone."}, {"id": "E07", "source": "V03", "target": "V16", "polarity": 1, "rationale": "Transport spending can improve usable public transport when affordability and accessibility are specified.", "status": "policy", "evidence": ["A16", "A25", "A30"], "delay": true, "scope": "Requires inclusive service design and operating support."}, {"id": "E08", "source": "V03", "target": "V17", "polarity": 1, "rationale": "Allocated street investment can deliver safer and more accessible active-travel routes.", "status": "policy", "evidence": ["A13", "A25", "A32"], "delay": true, "scope": ""}, {"id": "E09", "source": "V03", "target": "V06", "polarity": 1, "rationale": "Targeted housing programs can finance healthier homes for underserved residents.", "status": "policy", "evidence": ["A23", "A25"], "delay": true, "scope": "Assumes quality gains reach original priority residents and preserve affordability."}, {"id": "E10", "source": "V03", "target": "V07", "polarity": 1, "rationale": "Targeted retrofit programs can improve energy performance in priority households' homes.", "status": "policy", "evidence": ["A23", "A26"], "delay": true, "scope": "With appropriate ventilation, installation and financial support."}, {"id": "E11", "source": "V02", "target": "V05", "polarity": 1, "rationale": "Organized resident influence may help secure enforceable affordability and anti-displacement measures.", "status": "policy", "evidence": ["A16", "A26"], "delay": true, "scope": "Political translation is contingent, not guaranteed."}, {"id": "E12", "source": "V04", "target": "V03", "polarity": 1, "rationale": "An operational equity response can redirect resources to underserved needs.", "status": "policy", "evidence": ["A12", "A25", "A28"], "delay": true, "scope": "Requires monitoring, mandate, budget, coordination and implementation."}, {"id": "E13", "source": "V04", "target": "V05", "polarity": 1, "rationale": "An operational response can fund and enforce affordable housing protection.", "status": "policy", "evidence": ["A25", "A26"], "delay": true, "scope": "This is a proposed intervention response, not an observed automatic feedback."}, {"id": "E14", "source": "V33", "target": "V04", "polarity": 1, "rationale": "A detected widening of unmet-needs disparities may trigger stronger equity action.", "status": "policy", "evidence": ["A12", "A28"], "delay": true, "scope": "MODEL ASSUMPTION: institutions detect the gap and are willing and able to respond."}, {"id": "E15", "source": "V34", "target": "V04", "polarity": 1, "rationale": "Recognized unfair health gaps may increase the case for equity-oriented intervention.", "status": "policy", "evidence": ["A16", "A28"], "delay": true, "scope": "MODEL ASSUMPTION: evidence is translated into action; politics can weaken or block this link."}, {"id": "E16", "source": "V22", "target": "V04", "polarity": 1, "rationale": "A worsening injury burden among priority residents may prompt an equity-focused safety response.", "status": "policy", "evidence": ["A13", "A32"], "delay": true, "scope": "MODEL ASSUMPTION: surveillance identifies the burden and decision makers act."}, {"id": "E17", "source": "V05", "target": "V08", "polarity": -1, "rationale": "Effective affordability measures can reduce tenure-cost pressure on protected households.", "status": "policy", "evidence": ["A26"], "delay": true, "scope": "Refers to realized protective coverage, not any policy bearing an affordability label."}, {"id": "E18", "source": "V05", "target": "V10", "polarity": -1, "rationale": "Secure affordable provision and enforceable tenure safeguards can reduce insecurity.", "status": "policy", "evidence": ["A24", "A26"], "delay": true, "scope": ""}, {"id": "E19", "source": "V05", "target": "V11", "polarity": -1, "rationale": "Effective protections can help original residents remain through neighborhood change.", "status": "policy", "evidence": ["A26"], "delay": true, "scope": "Coverage, enforcement, eligibility and housing supply matter."}, {"id": "E20", "source": "V06", "target": "V12", "polarity": 1, "rationale": "Improved dwellings may become more desirable and command higher market costs.", "status": "reported", "evidence": ["A03"], "delay": true, "scope": "Market capitalization is weaker where affordability is permanently protected."}, {"id": "E21", "source": "V14", "target": "V12", "polarity": 1, "rationale": "Better shared green amenities can increase nearby housing demand and market costs.", "status": "reported", "evidence": ["A03", "A22"], "delay": true, "scope": "Contextual capitalization; benefits can be retained with safeguards."}, {"id": "E22", "source": "V15", "target": "V12", "polarity": 1, "rationale": "Market-valued amenity improvements accompanying better effective access may raise housing costs.", "status": "synthesis", "evidence": ["A03"], "delay": true, "scope": "Only where effective access accompanies market-valued amenity improvements. Affordability-only or accessibility-only changes need not raise prices."}, {"id": "E23", "source": "V12", "target": "V35", "polarity": 1, "rationale": "Higher entry and retention costs can select a wealthier neighborhood resident composition.", "status": "reported", "evidence": ["A04"], "delay": true, "scope": "COMPOSITIONAL SORTING ONLY: original residents are not assumed to gain income; protections can interrupt sorting."}, {"id": "E24", "source": "V12", "target": "V08", "polarity": 1, "rationale": "At unchanged household resources, higher rents or tenure payments increase cost burden.", "status": "reported", "evidence": ["A18"], "delay": false, "scope": "Exposed renters and purchasers; not every owner-occupier or protected tenancy."}, {"id": "E25", "source": "V13", "target": "V12", "polarity": 1, "rationale": "Market-led upgrading can increase rents and purchase prices.", "status": "reported", "evidence": ["A18", "A21"], "delay": true, "scope": "Magnitude and timing vary across markets and tenures."}, {"id": "E26", "source": "V13", "target": "V11", "polarity": 1, "rationale": "Neighborhood replacement processes may lead to forced moves among vulnerable original residents.", "status": "association", "evidence": ["A06", "A21"], "delay": true, "scope": "Displacement is possible, not inevitable; tenure safeguards moderate the link."}, {"id": "E27", "source": "V13", "target": "V15", "polarity": -1, "rationale": "Commercial replacement can reduce access to locally appropriate affordable services for original residents.", "status": "reported", "evidence": ["A20"], "delay": true, "scope": "Effective affordable access can fall even when aggregate amenity counts rise."}, {"id": "E28", "source": "V08", "target": "V10", "polarity": 1, "rationale": "Persistent tenure-cost strain can undermine confidence in retaining adequate housing.", "status": "synthesis", "evidence": ["A18", "A24"], "delay": false, "scope": ""}, {"id": "E29", "source": "V08", "target": "V29", "polarity": 1, "rationale": "Higher housing cost burden can intensify chronic financial strain.", "status": "reported", "evidence": ["A18"], "delay": false, "scope": ""}, {"id": "E30", "source": "V10", "target": "V29", "polarity": 1, "rationale": "Uncertain housing security can sustain psychological strain.", "status": "reported", "evidence": ["A24"], "delay": false, "scope": ""}, {"id": "E31", "source": "V08", "target": "V11", "polarity": 1, "rationale": "Unaffordable tenure costs can compel original residents to move.", "status": "reported", "evidence": ["A06", "A18"], "delay": true, "scope": "Conditional on resources, protections, arrears processes and available alternatives."}, {"id": "E32", "source": "V11", "target": "V28", "polarity": -1, "rationale": "Forced moves can break established support networks and local collective capacity.", "status": "reported", "evidence": ["A06", "A19"], "delay": true, "scope": "Follows original residents rather than improved neighborhood-average composition."}, {"id": "E33", "source": "V11", "target": "V29", "polarity": 1, "rationale": "Disruption and lost residential control can increase persistent strain.", "status": "association", "evidence": ["A06", "A19"], "delay": false, "scope": ""}, {"id": "E34", "source": "V01", "target": "V06", "polarity": 1, "rationale": "Household resources expand the feasible set of healthy homes and maintenance choices.", "status": "synthesis", "evidence": ["A22"], "delay": true, "scope": "Structural exclusion, market supply and discrimination may block this pathway."}, {"id": "E35", "source": "V06", "target": "V30", "polarity": -1, "rationale": "Reduced damp, pollutants and other housing hazards can reduce physical morbidity.", "status": "reported", "evidence": ["A23"], "delay": true, "scope": "Housing quality is multidimensional; no universal magnitude is asserted."}, {"id": "E36", "source": "V07", "target": "V09", "polarity": -1, "rationale": "Improved energy performance can reduce required energy expenditure for adequate comfort.", "status": "reported", "evidence": ["A23"], "delay": true, "scope": "Assumes service needs, tariffs, ventilation and financing costs do not offset savings."}, {"id": "E37", "source": "V09", "target": "V29", "polarity": 1, "rationale": "A larger required energy-cost share can intensify chronic household financial strain.", "status": "synthesis", "evidence": ["A23"], "delay": false, "scope": ""}, {"id": "E38", "source": "V14", "target": "V28", "polarity": 1, "rationale": "Welcoming, well-maintained shared places can enable inclusive social encounters.", "status": "reported", "evidence": ["A05", "A08", "A15"], "delay": true, "scope": ""}, {"id": "E39", "source": "V28", "target": "V14", "polarity": 1, "rationale": "Inclusive collective capacity can support shared-space stewardship and upkeep.", "status": "reported", "evidence": ["A05"], "delay": true, "scope": "Requires usable resident influence and maintenance opportunities."}, {"id": "E40", "source": "V28", "target": "V26", "polarity": -1, "rationale": "Collective efficacy and informal stewardship can reduce neglect and disorder.", "status": "reported", "evidence": ["A05"], "delay": true, "scope": ""}, {"id": "E41", "source": "V26", "target": "V27", "polarity": -1, "rationale": "Visible disorder can reduce feelings of neighborhood safety.", "status": "reported", "evidence": ["A05", "A10"], "delay": false, "scope": ""}, {"id": "E42", "source": "V27", "target": "V28", "polarity": 1, "rationale": "Feeling safe can support public-space use and neighborly interaction.", "status": "reported", "evidence": ["A05", "A10"], "delay": true, "scope": ""}, {"id": "E43", "source": "V27", "target": "V21", "polarity": 1, "rationale": "Perceived safety can increase willingness to walk, cycle and be active outdoors.", "status": "association", "evidence": ["A13", "A33"], "delay": false, "scope": ""}, {"id": "E44", "source": "V14", "target": "V29", "polarity": -1, "rationale": "Usable green space can provide opportunities for stress recovery.", "status": "association", "evidence": ["A08", "A24"], "delay": false, "scope": ""}, {"id": "E45", "source": "V14", "target": "V25", "polarity": -1, "rationale": "Vegetation and shade can reduce harmful heat experienced in shared places.", "status": "reported", "evidence": ["A09"], "delay": false, "scope": "Depends on actual canopy, design, use and local climate; public-space access is not a universal cooling proxy."}, {"id": "E46", "source": "V14", "target": "V21", "polarity": 1, "rationale": "Accessible pleasant open spaces can support outdoor physical activity.", "status": "association", "evidence": ["A11", "A24"], "delay": false, "scope": ""}, {"id": "E47", "source": "V18", "target": "V21", "polarity": 1, "rationale": "Connected nearby destinations can make walking and active trips more feasible.", "status": "reported", "evidence": ["A29"], "delay": true, "scope": ""}, {"id": "E48", "source": "V18", "target": "V19", "polarity": -1, "rationale": "Proximate connected destinations can reduce the need for private motorized trips.", "status": "reported", "evidence": ["A11", "A29"], "delay": true, "scope": "Mode substitution requires suitable services and feasible alternatives."}, {"id": "E49", "source": "V18", "target": "V27", "polarity": 1, "rationale": "Complementary uses can sustain street presence and informal surveillance.", "status": "reported", "evidence": ["A10"], "delay": false, "scope": "A contextual mechanism; density alone is not assigned a universal safety effect."}, {"id": "E50", "source": "V16", "target": "V19", "polarity": -1, "rationale": "Usable public transport can substitute for otherwise necessary car travel.", "status": "synthesis", "evidence": ["A29", "A30"], "delay": true, "scope": "Assumes mode substitution rather than exclusively additional journeys."}, {"id": "E51", "source": "V16", "target": "V28", "polarity": 1, "rationale": "Affordable accessible transport can enable social journeys and reduce exclusion.", "status": "reported", "evidence": ["A30"], "delay": true, "scope": ""}, {"id": "E52", "source": "V17", "target": "V21", "polarity": 1, "rationale": "Safe, accessible routes and crossings can make active travel more feasible.", "status": "reported", "evidence": ["A13", "A29", "A32"], "delay": true, "scope": ""}, {"id": "E53", "source": "V17", "target": "V22", "polarity": -1, "rationale": "Protective street design and speed management can reduce population injury burden.", "status": "reported", "evidence": ["A32"], "delay": true, "scope": "At comparable travel exposure; induced activity is represented separately."}, {"id": "E54", "source": "V21", "target": "V22", "polarity": 1, "rationale": "More time walking or cycling can increase exposure to road danger when infrastructure is unsafe.", "status": "association", "evidence": ["A32"], "delay": false, "scope": "CONDITIONAL COUNTERPATH: population injury risk, not per-trip risk. Safety-in-numbers and safer infrastructure can weaken or reverse the net relationship."}, {"id": "E55", "source": "V22", "target": "V27", "polarity": -1, "rationale": "Experienced or visible road danger may lower perceived safety of local travel.", "status": "synthesis", "evidence": ["A13", "A33"], "delay": false, "scope": "Risk perception is not identical to objectively measured injury risk."}, {"id": "E56", "source": "V19", "target": "V20", "polarity": 1, "rationale": "Greater reliance on private motorized trips tends to add vehicle traffic.", "status": "reported", "evidence": ["A31"], "delay": true, "scope": "Traffic also reflects through journeys, occupancy and freight."}, {"id": "E57", "source": "V20", "target": "V23", "polarity": 1, "rationale": "Additional vehicle traffic can increase pollutant emissions and local exposure.", "status": "reported", "evidence": ["A31"], "delay": false, "scope": "Depends on fleet, dispersion, proximity, routes and other sources."}, {"id": "E58", "source": "V20", "target": "V24", "polarity": 1, "rationale": "Motor traffic is a source of harmful environmental noise.", "status": "reported", "evidence": ["A14", "A31"], "delay": false, "scope": "Vehicle speeds, barriers, fleet and building design moderate exposure."}, {"id": "E59", "source": "V20", "target": "V22", "polarity": 1, "rationale": "Greater motor traffic can increase conflict exposure for vulnerable road users.", "status": "reported", "evidence": ["A32"], "delay": false, "scope": "Road design, speed and pedestrian/cyclist exposure held in context."}, {"id": "E60", "source": "V23", "target": "V30", "polarity": 1, "rationale": "Pollutant exposure can contribute to respiratory and cardiovascular morbidity.", "status": "reported", "evidence": ["A14", "A31"], "delay": true, "scope": ""}, {"id": "E61", "source": "V24", "target": "V29", "polarity": 1, "rationale": "Persistent noise can disturb sleep and activate stress responses.", "status": "reported", "evidence": ["A14", "A31"], "delay": false, "scope": ""}, {"id": "E62", "source": "V25", "target": "V30", "polarity": 1, "rationale": "Harmful heat can increase acute illness and aggravate existing physical disease.", "status": "reported", "evidence": ["A09", "A14"], "delay": false, "scope": "Vulnerability and access to cooling modify effects."}, {"id": "E63", "source": "V21", "target": "V30", "polarity": -1, "rationale": "Physical activity can reduce chronic physical disease risk.", "status": "reported", "evidence": ["A29"], "delay": true, "scope": "Not a promise of net benefit in every high-pollution or unsafe setting."}, {"id": "E64", "source": "V29", "target": "V30", "polarity": 1, "rationale": "Prolonged stress may contribute to cumulative physical disease pathways.", "status": "synthesis", "evidence": ["A14", "A31"], "delay": true, "scope": "A coarse synthesis, not a quantified stress–disease coefficient."}, {"id": "E65", "source": "V29", "target": "V31", "polarity": 1, "rationale": "Persistent stress can contribute to adverse mental health.", "status": "synthesis", "evidence": ["A14", "A19", "A24"], "delay": true, "scope": "Stress and clinical mental ill health are distinct constructs."}, {"id": "E66", "source": "V28", "target": "V29", "polarity": -1, "rationale": "Inclusive support networks can buffer persistent psychosocial strain.", "status": "reported", "evidence": ["A19", "A30"], "delay": false, "scope": ""}, {"id": "E67", "source": "V30", "target": "V32", "polarity": -1, "rationale": "Physical morbidity may reduce capacity to obtain and sustain paid work.", "status": "synthesis", "evidence": ["A34"], "delay": true, "scope": "UNTESTED CLOSURE: the source identifies productivity as an evidence gap; disability inclusion, employment protections and illness severity matter."}, {"id": "E68", "source": "V32", "target": "V01", "polarity": 1, "rationale": "Sustained paid work can increase household financial resources.", "status": "synthesis", "evidence": ["A16", "A34"], "delay": true, "scope": "MODEL ASSUMPTION: wage income is not fully offset by lost transfers or other expenses."}, {"id": "E69", "source": "V31", "target": "V32", "polarity": -1, "rationale": "Mental ill health may reduce sustainable work participation.", "status": "synthesis", "evidence": ["A16", "A34"], "delay": true, "scope": "UNTESTED CLOSURE: do not infer causality from the reviewed unemployment-to-distress association."}, {"id": "E70", "source": "V06", "target": "V33", "polarity": -1, "rationale": "Closing priority residents' healthy-housing shortfall can narrow the shelter-needs gap.", "status": "indicator", "evidence": ["A12", "A23"], "delay": false, "scope": "CONDITIONAL ACCOUNTING: the priority group's change must exceed the reference group's change; needs are assessed relative to group-specific requirements. No scalar weights or effect sizes are assumed."}, {"id": "E71", "source": "V15", "target": "V33", "polarity": -1, "rationale": "Removing priority residents' effective service-access barriers can narrow the access gap.", "status": "indicator", "evidence": ["A12", "A20"], "delay": false, "scope": "CONDITIONAL ACCOUNTING: the priority group's change must exceed the reference group's change; needs are assessed relative to group-specific requirements. No scalar weights or effect sizes are assumed."}, {"id": "E72", "source": "V16", "target": "V33", "polarity": -1, "rationale": "Meeting underserved groups' transport requirements can narrow unmet mobility needs.", "status": "indicator", "evidence": ["A12", "A16", "A30"], "delay": false, "scope": "CONDITIONAL ACCOUNTING: the priority group's change must exceed the reference group's change; needs are assessed relative to group-specific requirements. No scalar weights or effect sizes are assumed."}, {"id": "E73", "source": "V17", "target": "V33", "polarity": -1, "rationale": "Accessible safe routes can narrow underserved groups' mobility and safety shortfalls.", "status": "indicator", "evidence": ["A12", "A13", "A32"], "delay": false, "scope": "CONDITIONAL ACCOUNTING: the priority group's change must exceed the reference group's change; needs are assessed relative to group-specific requirements. No scalar weights or effect sizes are assumed."}, {"id": "E74", "source": "V10", "target": "V33", "polarity": 1, "rationale": "Disproportionately worsening housing insecurity can widen unmet shelter needs.", "status": "indicator", "evidence": ["A12", "A24"], "delay": false, "scope": "CONDITIONAL ACCOUNTING: the priority group's change must exceed the reference group's change; needs are assessed relative to group-specific requirements. No scalar weights or effect sizes are assumed."}, {"id": "E75", "source": "V25", "target": "V33", "polarity": 1, "rationale": "Disproportionate harmful heat exposure can widen unmet health-protection needs.", "status": "indicator", "evidence": ["A09", "A14"], "delay": false, "scope": "CONDITIONAL ACCOUNTING: the priority group's change must exceed the reference group's change; needs are assessed relative to group-specific requirements. No scalar weights or effect sizes are assumed."}, {"id": "E76", "source": "V27", "target": "V33", "polarity": -1, "rationale": "Improving priority groups' felt ability to use places safely can narrow the safety-needs gap.", "status": "indicator", "evidence": ["A10", "A12", "A33"], "delay": false, "scope": "CONDITIONAL ACCOUNTING: the priority group's change must exceed the reference group's change; needs are assessed relative to group-specific requirements. No scalar weights or effect sizes are assumed."}, {"id": "E77", "source": "V30", "target": "V34", "polarity": 1, "rationale": "Disproportionately worsening avoidable physical morbidity can widen the unfair health gap.", "status": "indicator", "evidence": ["A12", "A14"], "delay": false, "scope": "CONDITIONAL ACCOUNTING: the priority group's change must exceed the reference group's change; needs are assessed relative to group-specific requirements. No scalar weights or effect sizes are assumed."}, {"id": "E78", "source": "V31", "target": "V34", "polarity": 1, "rationale": "Disproportionately worsening avoidable mental morbidity can widen the unfair health gap.", "status": "indicator", "evidence": ["A12", "A19"], "delay": false, "scope": "CONDITIONAL ACCOUNTING: the priority group's change must exceed the reference group's change; needs are assessed relative to group-specific requirements. No scalar weights or effect sizes are assumed."}], "loops": [{"id": "R1", "name": "Cohesion and safety", "type": "R", "nodes": ["V28", "V26", "V27"], "edges": ["E40", "E41", "E42"], "mechanism": "Stronger cohesion reduces disorder. Lower disorder raises perceived safety; safer shared places support interaction and cohesion. The same loop can amplify decline in the opposite direction.", "equityEffect": "Can improve safety and social wellbeing for priority residents; unevenly distributed gains can still leave disparities unchanged.", "assumptions": ["Cohesion is inclusive, rather than exclusionary social control.", "Safety perceptions affect real opportunities for interaction."], "basis": "Simplified source-described reinforcing mechanism: S1 Section 3.4.3 and Figure 5; supported by S2.", "negativeLinks": 2, "polarityProduct": 1, "delay": true}, {"id": "R2", "name": "Shared-space stewardship", "type": "R", "nodes": ["V28", "V14"], "edges": ["E39", "E38"], "mechanism": "Collective capacity supports upkeep of shared places. Welcoming usable places enable encounters that rebuild that capacity.", "equityEffect": "A potential virtuous cycle where underserved residents retain usable access; a vicious cycle when neglect and withdrawal reinforce each other.", "assumptions": ["Residents have maintenance opportunities and shared spaces are welcoming.", "Physical improvement does not exclude the original residents."], "basis": "Simplified mutual reinforcement described in S1 Section 3.4.3 and Figure 5.", "negativeLinks": 0, "polarityProduct": 1, "delay": true}, {"id": "R3", "name": "Resources, voice and residential sorting", "type": "R", "nodes": ["V35", "V02", "V03", "V15", "V12"], "edges": ["E01", "E02", "E06", "E22", "E23"], "mechanism": "A wealthier resident composition supports greater influence and investment. Improved amenities increase housing costs, which can further select a wealthier resident composition.", "equityEffect": "Can concentrate advantages and exclude lower-resource residents. Higher neighborhood-average wealth is not evidence of gains for original residents.", "assumptions": ["Investment responds to effective influence rather than fully compensating need.", "Housing costs sort entry and retention; affordability protections can interrupt the loop.", "Effective service access accompanies market-valued amenity improvements; access gains alone do not necessarily raise prices.", "V35 is compositional and never substitutes for V01 household resources."], "basis": "Cross-theme reconstruction of S1 Sections 3.4.1–3.4.2; public investment is an explicit mediator added in this model.", "negativeLinks": 0, "polarityProduct": 1, "delay": true}, {"id": "R4", "name": "Stress and constrained voice", "type": "R", "nodes": ["V29", "V02", "V03", "V14"], "edges": ["E03", "E02", "E05", "E44"], "mechanism": "Persistent strain reduces influence. Weaker influence can limit local investment and shared-space quality, leaving fewer opportunities for stress recovery and perpetuating strain.", "equityEffect": "May trap underserved residents in a cycle of constrained control; targeted investment independent of political influence can weaken it.", "assumptions": ["Collective influence affects realized investment, and stressed priority residents form the relevant organizing base.", "Public-space quality is accessible to the same priority population.", "The composite closed path has not been empirically tested."], "basis": "Synthesis of S1 resource/voice mechanisms with S2 green-space stress pathways.", "negativeLinks": 2, "polarityProduct": 1, "delay": true}, {"id": "R5", "name": "Health and household resources", "type": "R", "nodes": ["V01", "V06", "V30", "V32"], "edges": ["E34", "E35", "E67", "E68"], "mechanism": "Resources widen healthy-housing options. Healthier homes can reduce physical morbidity, supporting paid work and household resources; declining resources can reverse the sequence.", "equityEffect": "A plausible disadvantage trap or virtuous cycle for original priority households, depending on housing supply, employment support and social protection.", "assumptions": ["Health-to-work and work-to-resources are explicitly untested synthesis closures.", "Income support and inclusive employment can decouple illness from resources.", "Housing improvements reach original residents without unaffordable cost increases."], "basis": "Hypothesized cross-source loop. S5 supports housing pathways; S6 calls for downstream productivity evidence rather than validating this closure.", "negativeLinks": 2, "polarityProduct": 1, "delay": true}, {"id": "B1", "name": "Equity-responsive housing protection", "type": "B", "nodes": ["V33", "V04", "V05", "V10"], "edges": ["E14", "E13", "E18", "E74"], "mechanism": "A widening needs gap is detected and acted on. Effective housing protections reduce insecurity, which can reduce the disproportionate unmet shelter need that triggered action.", "equityEffect": "Can reduce shelter inequity if measures reach underserved original residents; delayed or unfunded responses leave the loop inactive.", "assumptions": ["Monitoring and political willingness activate the response.", "Protections are financed, enforced and accessible.", "Priority-group improvement exceeds reference-group improvement."], "basis": "Proposed policy balancing loop; response activation is a model assumption informed by S2 and S5 recommendations.", "negativeLinks": 1, "polarityProduct": -1, "delay": true}, {"id": "B2", "name": "Equity-responsive transport access", "type": "B", "nodes": ["V33", "V04", "V03", "V16"], "edges": ["E14", "E12", "E07", "E72"], "mechanism": "Detected mobility shortfalls prompt an equity response and targeted spending. Inclusive public transport reduces priority residents' unmet mobility needs and the disparity prompting action.", "equityEffect": "Can reduce access and mobility inequities; capital spending alone is insufficient without affordable reliable operations.", "assumptions": ["Needs monitoring identifies the mobility component of the gap.", "Budgets are directed to underserved groups and translate into usable transport.", "The disparity indicator is conditional on relative improvement."], "basis": "Proposed policy balancing loop; S2, S3, S5 and S6 motivate interventions but do not establish automatic feedback.", "negativeLinks": 1, "polarityProduct": -1, "delay": true}, {"id": "B3", "name": "Safety-responsive street investment", "type": "B", "nodes": ["V22", "V04", "V03", "V17"], "edges": ["E16", "E12", "E08", "E53"], "mechanism": "An injury burden prompts action and street investment. Delivered protective infrastructure lowers road danger, reducing the signal that triggered intervention.", "equityEffect": "Can reduce unequal injury burdens when surveillance and design prioritize vulnerable road users; effects depend on travel exposure.", "assumptions": ["The injury signal activates an equity-focused response.", "Investment is delivered, maintained and protective at comparable exposure.", "Safety-in-numbers and induced activity can change net injury rates."], "basis": "Conditional intervention loop based on S6 traffic-safety measures and S3 inclusive-city recommendations.", "negativeLinks": 1, "polarityProduct": -1, "delay": true}, {"id": "B4", "name": "Amenity gains eroded by displacement", "type": "B", "nodes": ["V28", "V14", "V12", "V08", "V11"], "edges": ["E39", "E21", "E24", "E31", "E32"], "mechanism": "Cohesion improves shared spaces, but amenities can raise housing costs and tenure burden. Forced moves can break the original residents' networks, weakening the cohesion that helped produce the gains.", "equityEffect": "This balancing loop can undermine equity: it erodes original residents' social benefits. Balancing does not mean socially beneficial.", "assumptions": ["Housing costs capitalize amenity improvements.", "Original residents lack sufficient protection against unaffordable tenure costs.", "Track displaced people, not only the changing neighborhood population."], "basis": "Cross-source synthesis: S1 stewardship and capitalization, S4/S5 displacement pathways. No universal gentrification effect is assumed.", "negativeLinks": 1, "polarityProduct": -1, "delay": true}, {"id": "B5", "name": "Unsafe active-travel constraint", "type": "B", "nodes": ["V21", "V22", "V27"], "edges": ["E54", "E55", "E43"], "mechanism": "In an unsafe road environment, additional active travel can expose more residents to injury. Perceived danger may discourage activity, constraining the initial increase.", "equityEffect": "Can suppress mobility and health opportunities for vulnerable groups. Safer design can interrupt this adverse constraint.", "assumptions": ["Conditional on unsafe infrastructure and insufficient protection.", "Injury risk is population-level, not risk per trip; safety-in-numbers may change the sign.", "Measured injury risk and perceived danger are not identical."], "basis": "Conditional counterpath from S6 Sections 5.4–5.5 and S3 safety concerns; the closed loop is a synthesis hypothesis.", "negativeLinks": 1, "polarityProduct": -1, "delay": false}], "anchors": [{"id": "A01", "sourceId": "S1", "locator": "Section 3.4.1; article p.4 / repository PDF p.5", "paraphrase": "Resources strengthen collective influence; influence attracts investment and protects neighborhood conditions.", "url": "https://pure.eur.nl/ws/files/219230304/Understanding_the_systems_dynamics_of_neighborhood_socioeconomic_inequities_in_health_in_European_cities.pdf"}, {"id": "A02", "sourceId": "S1", "locator": "Section 3.4.1; article p.4 / PDF p.5", "paraphrase": "Stress inhibits collective engagement; material resources buffer strain.", "url": "https://pure.eur.nl/ws/files/219230304/Understanding_the_systems_dynamics_of_neighborhood_socioeconomic_inequities_in_health_in_European_cities.pdf"}, {"id": "A03", "sourceId": "S1", "locator": "Section 3.4.2; article p.5 / PDF p.6", "paraphrase": "Amenities, housing and green-space quality increase desirability and housing prices.", "url": "https://pure.eur.nl/ws/files/219230304/Understanding_the_systems_dynamics_of_neighborhood_socioeconomic_inequities_in_health_in_European_cities.pdf"}, {"id": "A04", "sourceId": "S1", "locator": "Section 3.4.2; article p.5 / PDF p.6", "paraphrase": "Housing affordability sorts neighborhood socioeconomic composition, rather than raising incumbent incomes.", "url": "https://pure.eur.nl/ws/files/219230304/Understanding_the_systems_dynamics_of_neighborhood_socioeconomic_inequities_in_health_in_European_cities.pdf"}, {"id": "A05", "sourceId": "S1", "locator": "Section 3.4.3 and Figure 5; article pp.5–7 / PDF pp.6–8", "paraphrase": "Cohesion discourages disorder; safety supports interaction; shared-space upkeep and cohesion reinforce each other.", "url": "https://pure.eur.nl/ws/files/219230304/Understanding_the_systems_dynamics_of_neighborhood_socioeconomic_inequities_in_health_in_European_cities.pdf"}, {"id": "A06", "sourceId": "S1", "locator": "Section 6; article p.8 / PDF p.9", "paraphrase": "Rising housing costs can displace residents, disrupt networks and intensify stress.", "url": "https://pure.eur.nl/ws/files/219230304/Understanding_the_systems_dynamics_of_neighborhood_socioeconomic_inequities_in_health_in_European_cities.pdf"}, {"id": "A07", "sourceId": "S1", "locator": "Section 2.1.5 p.3 and Section 7 p.8 / PDF pp.4,9", "paraphrase": "Connections are expert hypotheses; the diagram does not identify strict epidemiological causality.", "url": "https://pure.eur.nl/ws/files/219230304/Understanding_the_systems_dynamics_of_neighborhood_socioeconomic_inequities_in_health_in_European_cities.pdf"}, {"id": "A08", "sourceId": "S2", "locator": "Availability of green areas; article p.741", "paraphrase": "Usable green space supports encounters and recovery from stress.", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4721462/"}, {"id": "A09", "sourceId": "S2", "locator": "Climate characteristics; article p.741", "paraphrase": "Vegetation cools urban environments; heat vulnerability differs by resources, age and isolation.", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4721462/"}, {"id": "A10", "sourceId": "S2", "locator": "Link 2: social conditions; article p.742", "paraphrase": "Neglect signals danger; mixed uses support surveillance; fear discourages activity and interaction.", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4721462/"}, {"id": "A11", "sourceId": "S2", "locator": "Physical activity and active mobility; article p.742", "paraphrase": "Car-oriented separation increases driving; safe accessible destinations support activity, with unequal use.", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4721462/"}, {"id": "A12", "sourceId": "S2", "locator": "Discussion and conclusions; article pp.743–744", "paraphrase": "Tailored interventions must address unequal starting conditions; equal facility counts cannot establish equity.", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4721462/"}, {"id": "A13", "sourceId": "S3", "locator": "Health behaviors within the cities; PDF pp.3–4", "paraphrase": "Walkability and safe recreation support activity; safety concerns impede participation.", "url": "https://link.springer.com/content/pdf/10.1007/s40520-025-03052-1.pdf#page=4"}, {"id": "A14", "sourceId": "S3", "locator": "Environmental risk factors; PDF pp.6–7", "paraphrase": "Air pollution, heat and noise create health burdens through biological and psychological pathways.", "url": "https://link.springer.com/content/pdf/10.1007/s40520-025-03052-1.pdf#page=6"}, {"id": "A15", "sourceId": "S3", "locator": "Structural factors; PDF p.8", "paraphrase": "Green infrastructure enables social interaction; housing crowding contributes to distress.", "url": "https://link.springer.com/content/pdf/10.1007/s40520-025-03052-1.pdf#page=8"}, {"id": "A16", "sourceId": "S3", "locator": "Age-friendly cities; governance; mental health services; PDF p.11", "paraphrase": "Inclusive infrastructure and participatory governance are recommended; unemployment is a distress pathway.", "url": "https://link.springer.com/content/pdf/10.1007/s40520-025-03052-1.pdf#page=11"}, {"id": "A17", "sourceId": "S3", "locator": "Healthcare access; PDF p.10", "paraphrase": "Treatment costs can worsen poverty without financial protection.", "url": "https://link.springer.com/content/pdf/10.1007/s40520-025-03052-1.pdf#page=10"}, {"id": "A18", "sourceId": "S4", "locator": "Section 4 and Figure 5; PDF p.11", "paraphrase": "Higher housing costs squeeze resources, create displacement pressure and financial distress.", "url": "https://www.frontiersin.org/journals/public-health/articles/10.3389/fpubh.2023.1154515/pdf#page=11"}, {"id": "A19", "sourceId": "S4", "locator": "Section 4 and Figure 5; PDF p.12", "paraphrase": "Social displacement disrupts support; isolation harms wellbeing; collective efficacy can buffer gentrification harms.", "url": "https://www.frontiersin.org/journals/public-health/articles/10.3389/fpubh.2023.1154515/pdf#page=12"}, {"id": "A20", "sourceId": "S4", "locator": "Section 4; PDF p.12", "paraphrase": "Commercial displacement can reduce access to affordable food and locally appropriate services.", "url": "https://www.frontiersin.org/journals/public-health/articles/10.3389/fpubh.2023.1154515/pdf#page=12"}, {"id": "A21", "sourceId": "S4", "locator": "Sections 3.6.1–3.6.3; PDF pp.9–11", "paraphrase": "Gentrification's health effects vary by population, tenure and time; displacement is not universal.", "url": "https://www.frontiersin.org/journals/public-health/articles/10.3389/fpubh.2023.1154515/pdf#page=10"}, {"id": "A22", "sourceId": "S5", "locator": "Introduction; PDF p.2", "paraphrase": "Market barriers exclude disadvantaged households; green upgrades can increase costs and displacement.", "url": "https://researchers-admin.westernsydney.edu.au/ws/portalfiles/portal/319751755/sustainability-17-07519.pdf#page=2"}, {"id": "A23", "sourceId": "S5", "locator": "Sections 4.2–4.3 and Table 1; PDF pp.5–6", "paraphrase": "Ventilation, moisture control and safer materials support respiratory health; efficient housing reduces energy stress.", "url": "https://researchers-admin.westernsydney.edu.au/ws/portalfiles/portal/319751755/sustainability-17-07519.pdf#page=6"}, {"id": "A24", "sourceId": "S5", "locator": "Table 1; PDF p.6", "paraphrase": "Affordable inclusive housing reduces insecurity and associated distress; green spaces support activity and wellbeing.", "url": "https://researchers-admin.westernsydney.edu.au/ws/portalfiles/portal/319751755/sustainability-17-07519.pdf#page=6"}, {"id": "A25", "sourceId": "S5", "locator": "Section 5; PDF p.11", "paraphrase": "Coordinated funding, zoning and standards can support healthy housing; cost and political barriers impede implementation.", "url": "https://researchers-admin.westernsydney.edu.au/ws/portalfiles/portal/319751755/sustainability-17-07519.pdf#page=11"}, {"id": "A26", "sourceId": "S5", "locator": "Section 6; PDF p.12", "paraphrase": "Affordable units, rent protections and community-led housing are proposed to retain benefits for vulnerable residents.", "url": "https://researchers-admin.westernsydney.edu.au/ws/portalfiles/portal/319751755/sustainability-17-07519.pdf#page=12"}, {"id": "A27", "sourceId": "S5", "locator": "Section 8; PDF pp.13–14", "paraphrase": "Climate-responsive housing and cooling designs can protect vulnerable residents from heat and disaster exposure.", "url": "https://researchers-admin.westernsydney.edu.au/ws/portalfiles/portal/319751755/sustainability-17-07519.pdf#page=13"}, {"id": "A28", "sourceId": "S5", "locator": "Section 9; PDF pp.14–15", "paraphrase": "Longitudinal evidence and monitoring are needed; coalitions and resident engagement can influence policy.", "url": "https://researchers-admin.westernsydney.edu.au/ws/portalfiles/portal/319751755/sustainability-17-07519.pdf#page=14"}, {"id": "A29", "sourceId": "S6", "locator": "Sections 3–4.1; accepted manuscript pp.6–10", "paraphrase": "Connected mixed uses, active infrastructure and transit support walking; activity protects against chronic disease.", "url": "https://ora.ox.ac.uk/objects/uuid%3A9c42ba3a-ca01-425e-8982-69434adc1b25/download_file?safe_filename=BE-Health_final.pdf&type_of_work=Journal+article#page=9"}, {"id": "A30", "sourceId": "S6", "locator": "Section 4.3; accepted manuscript p.13", "paraphrase": "Transport access reduces exclusion; shared places enable social contact; commuting can crowd out social time.", "url": "https://ora.ox.ac.uk/objects/uuid%3A9c42ba3a-ca01-425e-8982-69434adc1b25/download_file?safe_filename=BE-Health_final.pdf&type_of_work=Journal+article#page=13"}, {"id": "A31", "sourceId": "S6", "locator": "Sections 5.1–5.3; accepted manuscript pp.14–17", "paraphrase": "Car dependence generates traffic emissions; pollution damages cardiopulmonary health; noise disrupts sleep and increases stress.", "url": "https://ora.ox.ac.uk/objects/uuid%3A9c42ba3a-ca01-425e-8982-69434adc1b25/download_file?safe_filename=BE-Health_final.pdf&type_of_work=Journal+article#page=14"}, {"id": "A32", "sourceId": "S6", "locator": "Section 5.4; accepted manuscript pp.17–18", "paraphrase": "Road design and speed influence injury; more active-travel exposure can increase injuries without protective measures.", "url": "https://ora.ox.ac.uk/objects/uuid%3A9c42ba3a-ca01-425e-8982-69434adc1b25/download_file?safe_filename=BE-Health_final.pdf&type_of_work=Journal+article#page=17"}, {"id": "A33", "sourceId": "S6", "locator": "Section 5.5; accepted manuscript pp.18–19", "paraphrase": "Perceived danger discourages walking and park use; disorder and insecurity contribute to distress.", "url": "https://ora.ox.ac.uk/objects/uuid%3A9c42ba3a-ca01-425e-8982-69434adc1b25/download_file?safe_filename=BE-Health_final.pdf&type_of_work=Journal+article#page=18"}, {"id": "A34", "sourceId": "S6", "locator": "Abstract; Introduction; conclusions; manuscript pp.2–3,20–21", "paraphrase": "Workforce productivity and downstream costs require further investigation; a complete feedback model is not estimated.", "url": "https://ora.ox.ac.uk/objects/uuid%3A9c42ba3a-ca01-425e-8982-69434adc1b25/download_file?safe_filename=BE-Health_final.pdf&type_of_work=Journal+article#page=23"}], "sources": [{"id": "S1", "authors": "Vernon Cail et al.", "year": 2026, "title": "Understanding the systems dynamics of neighborhood socioeconomic inequities in health in European cities: a causal loop diagram", "journal": "Health & Place 97, 103595", "doi": "10.1016/j.healthplace.2025.103595", "fullTextUrl": "https://pure.eur.nl/ws/files/219230304/Understanding_the_systems_dynamics_of_neighborhood_socioeconomic_inequities_in_health_in_European_cities.pdf", "access": "Open-access journal article / university repository PDF", "note": "Scoping review and expert model building: 85 studies, 22 factors and 64 connections. Expert-hypothesized arrows; not epidemiological causal identification. Repository PDF has a cover: PDF page = article page + 1. The PPT spells Cail as Cali and says around 70 articles; the original paper takes precedence.", "url": "https://doi.org/10.1016/j.healthplace.2025.103595"}, {"id": "S2", "authors": "Elena Gelormino, Giulia Melis, Cristina Marietta and Giuseppe Costa", "year": 2015, "title": "From built environment to health inequalities: An explanatory framework based on evidence", "journal": "Preventive Medicine Reports 2, 737–745", "doi": "10.1016/j.pmedr.2015.08.019", "fullTextUrl": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4721462/", "access": "Open-access full text", "note": "Review framework. Equity effects depend on social position and effective use; equal facility provision is insufficient. No universal direction is assigned to urban density.", "url": "https://doi.org/10.1016/j.pmedr.2015.08.019"}, {"id": "S3", "authors": "Stefano Cacciatore et al.", "year": 2025, "title": "Urban health inequities and healthy longevity: traditional and emerging risk factors across the cities and policy implications", "journal": "Aging Clinical and Experimental Research 37, 143", "doi": "10.1007/s40520-025-03052-1", "fullTextUrl": "https://link.springer.com/article/10.1007/s40520-025-03052-1", "access": "Open-access journal full text", "note": "Narrative review. Heterogeneous evidence and policy recommendations; no estimated closed feedback responses.", "url": "https://doi.org/10.1007/s40520-025-03052-1"}, {"id": "S4", "authors": "Sun Delong (publisher citation: Delong S)", "year": 2023, "title": "Urban health inequality in shifting environment: systematic review on the impact of gentrification on residents' health", "journal": "Frontiers in Public Health 11, 1154515", "doi": "10.3389/fpubh.2023.1154515", "fullTextUrl": "https://www.frontiersin.org/journals/public-health/articles/10.3389/fpubh.2023.1154515/full", "access": "Open-access full text", "note": "Systematic review of 66 empirical studies, predominantly Western and often cross-sectional. Displacement and health effects are heterogeneous. The author's displayed name and publisher citation differ in order.", "url": "https://doi.org/10.3389/fpubh.2023.1154515"}, {"id": "S5", "authors": "Kritika Rana", "year": 2025, "title": "Sustainable Housing as a Social Determinant of Health and Wellbeing", "journal": "Sustainability 17(16), 7519", "doi": "10.3390/su17167519", "fullTextUrl": "https://researchers-admin.westernsydney.edu.au/ws/portalfiles/portal/319751755/sustainability-17-07519.pdf", "access": "Open-access journal PDF / university repository", "note": "Integrative review of sustainable housing, health, equity and policy. This is the PPT's Rana paper; it is not the earlier migrant/refugee housing review.", "url": "https://doi.org/10.3390/su17167519"}, {"id": "S6", "authors": "Lawrence D. Frank, Nicole Iroz-Elardo, Kara E. MacLeod and Andy Hong", "year": 2019, "title": "Pathways from built environment to health: A conceptual framework linking behavior and exposure-based impacts", "journal": "Journal of Transport & Health 12, 319–335", "doi": "10.1016/j.jth.2018.11.008", "fullTextUrl": "https://ora.ox.ac.uk/objects/uuid%3A9c42ba3a-ca01-425e-8982-69434adc1b25/download_file?safe_filename=BE-Health_final.pdf&type_of_work=Journal+article", "access": "Author-accepted manuscript in Oxford University Research Archive", "note": "Conceptual synthesis separating behavioral and exposure pathways. Page locators here refer to the 33-page accepted manuscript, not publisher pagination. Feedbacks are acknowledged but not drawn; health–work closure remains a synthesis hypothesis.", "url": "https://doi.org/10.1016/j.jth.2018.11.008"}], "provenance": {"brief": "Automated CLD input parameters.pptx", "briefSha256": "623d989b04a6ff482e54e35a037ca6ea949e5faf6d4c5dfa2d1e2d2585691290", "slides": "1: problem, target and equity definition; 2–7: six source titles; 8: definition references.", "sourceSelection": "Only the six papers named on slides 2–7 inform the substantive causal model. Earlier local PDFs and the previous CLD are superseded, not reused as evidence.", "verifiedOn": "2026-10-20", "targetVariables": "Approximately 30–35; implemented 35.", "corrections": ["Cali in the PPT corrected to Cail from S1.", "S1 reports 85 reviewed studies, not the PPT's around 70.", "S5 is the sustainable-housing review specified in the PPT.", "The PPT enumerates five needs after announcing six; five are modeled."], "statusDefinitions": {"reported": "A directional mechanism discussed by a source, including conceptual hypotheses; not proof of causation.", "association": "An observed/reviewed association given a proposed direction; confounding and reverse causality remain possible.", "synthesis": "An explicit modeling inference or cross-source bridge; not directly established as this arrow.", "policy": "A proposed, conditional intervention or response; not an automatic or empirically measured feedback.", "indicator": "Conditional group-difference accounting; improvement must exceed the reference group's change."}}};
